import React, { useState } from 'react';
import '../styles/components.css';

function AdvancedAnalysisViewer({ plotData, fileName }) {
  const [activeTab, setActiveTab] = useState('ml');

  // Add debugging
  console.log('AdvancedAnalysisViewer received plotData:', plotData);
  console.log('Available keys in plotData:', Object.keys(plotData || {}));

  if (!plotData) {
    return (
      <div className="advanced-analysis-container">
        <p>No advanced analysis data available</p>
      </div>
    );
  }

  // Extract ML results from plotData
  const mlResults = plotData.ml_results || plotData.features || {};
  const plots = plotData.plots || {};
  const features = plotData.features || {};

  console.log('ML Results:', mlResults);
  console.log('Available plots:', Object.keys(plots));
  console.log('Features:', features);

  const renderMLAnalysis = () => {
    if (!mlResults || Object.keys(mlResults).length === 0) {
      return (
        <div className="tab-content">
          <h4>Machine Learning Analysis</h4>
          <p>No ML analysis data available</p>
          <p>Debug: mlResults = {JSON.stringify(mlResults, null, 2)}</p>
        </div>
      );
    }

    return (
      <div className="tab-content">
        <h4>Machine Learning Analysis</h4>
        
        {/* Best Classifier Info */}
        {mlResults.best_classifier && (
          <div className="ml-summary">
            <h5>Best Classifier: {mlResults.best_classifier}</h5>
            <p>Accuracy: {mlResults.accuracy ? (mlResults.accuracy * 100).toFixed(2) : 'N/A'}%</p>
          </div>
        )}

        {/* Feature Importance Plot */}
        {mlResults.plots?.feature_importance && (
          <div className="plot-item">
            <h5>Feature Importance</h5>
            <img 
              src={`data:image/png;base64,${mlResults.plots.feature_importance}`}
              alt="Feature Importance"
              style={{ maxWidth: '100%', height: 'auto' }}
            />
          </div>
        )}

        {/* Classifier Comparison */}
        {mlResults.plots?.classifier_comparison && (
          <div className="plot-item">
            <h5>Classifier Comparison</h5>
            <img 
              src={`data:image/png;base64,${mlResults.plots.classifier_comparison}`}
              alt="Classifier Comparison"
              style={{ maxWidth: '100%', height: 'auto' }}
            />
          </div>
        )}

        {/* Confusion Matrix */}
        {mlResults.plots?.confusion_matrix && (
          <div className="plot-item">
            <h5>Confusion Matrix</h5>
            <img 
              src={`data:image/png;base64,${mlResults.plots.confusion_matrix}`}
              alt="Confusion Matrix"
              style={{ maxWidth: '100%', height: 'auto' }}
            />
          </div>
        )}

        {/* Learning Curve */}
        {mlResults.plots?.learning_curve && (
          <div className="plot-item">
            <h5>Learning Curve</h5>
            <img 
              src={`data:image/png;base64,${mlResults.plots.learning_curve}`}
              alt="Learning Curve"
              style={{ maxWidth: '100%', height: 'auto' }}
            />
          </div>
        )}

        {/* Top Features */}
        {mlResults.top_features && mlResults.top_features.length > 0 && (
          <div className="top-features">
            <h5>Top Discriminating Features</h5>
            <ol>
              {mlResults.top_features.slice(0, 10).map((feature, index) => (
                <li key={index}>{feature}</li>
              ))}
            </ol>
          </div>
        )}

        {/* Hyperparameter Results */}
        {mlResults.params && Object.keys(mlResults.params).length > 0 && (
          <div className="hyperparameters">
            <h5>Hyperparameter Tuning Results</h5>
            {Object.entries(mlResults.params).map(([classifier, params]) => (
              <div key={classifier}>
                <h6>{classifier}</h6>
                <pre>{JSON.stringify(params, null, 2)}</pre>
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  const renderConnectivityAnalysis = () => {
    return (
      <div className="tab-content">
        <h4>Connectivity Analysis</h4>
        <p>Connectivity analysis features coming soon...</p>
      </div>
    );
  };

  const renderSpectralAnalysis = () => {
    return (
      <div className="tab-content">
        <h4>Spectral Analysis</h4>
        <p>Spectral analysis features coming soon...</p>
      </div>
    );
  };

  const renderQualityAssessment = () => {
    return (
      <div className="tab-content">
        <h4>Signal Quality Assessment</h4>
        <p>Signal quality assessment features coming soon...</p>
      </div>
    );
  };

  return (
    <div className="advanced-analysis-container">
      <div className="analysis-tabs">
        <button 
          className={`tab-button ${activeTab === 'ml' ? 'active' : ''}`}
          onClick={() => setActiveTab('ml')}
        >
          🤖 Machine Learning
        </button>
        <button 
          className={`tab-button ${activeTab === 'connectivity' ? 'active' : ''}`}
          onClick={() => setActiveTab('connectivity')}
        >
          🔗 Connectivity
        </button>
        <button 
          className={`tab-button ${activeTab === 'spectral' ? 'active' : ''}`}
          onClick={() => setActiveTab('spectral')}
        >
          📊 Spectral
        </button>
        <button 
          className={`tab-button ${activeTab === 'quality' ? 'active' : ''}`}
          onClick={() => setActiveTab('quality')}
        >
          ✅ Quality
        </button>
      </div>

      <div className="tab-content-container">
        {activeTab === 'ml' && renderMLAnalysis()}
        {activeTab === 'connectivity' && renderConnectivityAnalysis()}
        {activeTab === 'spectral' && renderSpectralAnalysis()}
        {activeTab === 'quality' && renderQualityAssessment()}
      </div>
    </div>
  );
}

export default AdvancedAnalysisViewer;
